; rows.asm -- chapter 41: a row from 0 to 23, three ways
; generated by gen41.py
        INCLUDE "msx.inc"
        OUTPUT "rows.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; rows.asm: a row from 0 to 23 three ways, over random's period: by
; rejection, by multiplication and by remainder; the rows counted.
seed    EQU VARS                ; random's state, two bytes
seed8   EQU VARS + 2            ; lcg's
num     EQU VARS + 3            ; strips: the number, and the bits left
left    EQU VARS + 4
counts  EQU $C400               ; rows.asm: 3 x 24 counts of two bytes
init:   di
        ld sp, SYS_AREA
        ld hl, counts           ; the counts: 3 x 24 rows, two bytes each
        ld de, counts + 1
        ld bc, 3 * 48 - 1
        ld (hl), 0
        ldir
        ld hl, 1
        ld (seed), hl
        ld hl, 65535
rj1:    push hl
        call rowrej
        ld hl, counts
        call count
        pop hl
        dec hl
        ld a, h
        or l
        jr nz, rj1
rejected:
        ld hl, 1
        ld (seed), hl
        ld hl, 65535
mu1:    push hl
        call random
        call rowmul
        ld hl, counts + 48
        call count
        pop hl
        dec hl
        ld a, h
        or l
        jr nz, mu1
multiplied:
        ld hl, 1
        ld (seed), hl
        ld hl, 65535
mo1:    push hl
        call random
        call rowmod
        ld hl, counts + 96
        call count
        pop hl
        dec hl
        ld a, h
        or l
        jr nz, mo1
done:   jr done

; count: A = a row, HL = its table -> the row's count, two bytes, one more
count:  add a, a
        add a, l
        ld l, a                 ; the table does not cross a page
        inc (hl)
        ret nz
        inc l
        inc (hl)
        ret

; random: the next of the 65,535 states of a 16-bit xorshift, x XOR x << 7,
; XOR x >> 9, XOR x << 8 -> seed, A = its high byte. Uses A, HL
random: ld hl, (seed)           ; 17
        ld a, h                 ;  5
        rra                     ;  5  bit 0 of H into the carry
        ld a, l                 ;  5
        rra                     ;  5  x << 7's high byte: that bit and L >> 1
        xor h                   ;  5
        ld h, a                 ;  5  H XOR it
        ld a, l                 ;  5
        rrca                    ;  5
        and $80                 ;  8  x << 7's low byte: L's bit 0 at bit 7
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x << 7
        ld a, h                 ;  5
        srl a                   ; 10  x >> 9, which is H >> 1
        xor l                   ;  5
        ld l, a                 ;  5  x XOR x >> 9, which changes L alone
        xor h                   ;  5
        ld h, a                 ;  5  x XOR x << 8: H XOR L
        ld (seed), hl           ; 17
        ret                     ; 11

; rowrej: A = a row from 0 to 23, from random's numbers AND 31, until one is
; below 24. Uses A, HL
rowrej: call random             ; 18
        and 31                  ;  8
        cp 24                   ;  8
        jr nc, rowrej           ; 13, or 8  24 to 31: another
        ret                     ; 11

; rowmul: A = a number -> A = A x 24 / 256, a row from 0 to 23. Uses A, DE, HL
rowmul: ld l, a                 ;  5
        ld h, 0                 ;  8
        ld e, l                 ;  5
        ld d, h                 ;  5
        add hl, hl              ; 12
        add hl, de              ; 12  3 x
        add hl, hl              ; 12
        add hl, hl              ; 12
        add hl, hl              ; 12  24 x
        ld a, h                 ;  5  / 256
        ret                     ; 11

; rowmod: A = a number -> A = A MOD 24, a row from 0 to 23. Uses A
rowmod: sub 24                  ;  8
        jr nc, rowmod           ; 13, or 8
        add a, 24               ;  8  one 24 too many
        ret                     ; 11
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
